// src/services/productStore.js

import request from "@/utils/request"; // 引入统一的请求工具

export const productService = {
  // 获取所有产品
  async fetchProducts() {
    return request.get("/api/products");
  },

  // 获取特定产品
  async fetchProductDetails(productId) {
    return request.get(`/api/products/${productId}`);
  },

  // 创建新产品
  async createProduct(productData) {
    return request.post("/api/products", productData); // 假设后端有处理 POST /api/products 的路由
  },

  // 更新产品信息
  async updateProduct(productId, updatedData) {
    return request.put(`/api/products/${productId}`, updatedData); // 假设后端有处理 PUT /api/products/:id 的路由
  },

  // 删除特定产品
  async deleteProduct(productId) {
    return request.delete(`/api/products/${productId}`); // 假设后端有处理 DELETE /api/products/:id 的路由
  },
};
